import numpy as np

def yin(x, fs, fmin=60, fmax=500, thresh=0.15):
    max_lag, min_lag = int(fs / fmin), int(fs / fmax)
    d = np.empty(max_lag + 1)
    for lag in range(1, max_lag + 1):
        diff = x[:len(x) - lag] - x[lag:]
        d[lag] = diff @ diff
    d[0] = 1.0
    cumulative = np.cumsum(d[1:]) / np.arange(1, max_lag + 1)
    dp = np.concatenate(([1.0], d[1:] / cumulative))

    for lag in range(min_lag, max_lag + 1):
        if dp[lag] < thresh:
            while lag + 1 <= max_lag and dp[lag + 1] < dp[lag]:
                lag += 1                       # walk to the bottom of THIS dip
            return fs / lag
    return 0.0                                 # unvoiced: report it, do not guess
